const productKeys = {
  all: ["products"] as const,
  lists: () => [...productKeys.all, "list"] as const,
  list: (params: ListParams) => [...productKeys.lists(), params] as const,
  detail: (id: number) => [...productKeys.all, "detail", id] as const,
};

function useProducts(params: ListParams) {
  return useQuery({
    queryKey: productKeys.list(params),
    queryFn: () => api.listProducts(params),
    staleTime: 30_000, // fresh for 30 s: no background refetch on mount or focus
  });
}

function useUpdateProduct() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: api.updateProduct,
    onSuccess: (product) => {
      queryClient.setQueryData(productKeys.detail(product.id), product);
      return queryClient.invalidateQueries({ queryKey: productKeys.lists() });
    },
  });
}
